import { corsHeaders, handleCorsPreflight, rejectDisallowedOrigin, serveWithKandidCors } from "../_shared/kandidProductionSecurity.mjs";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.104.1";
import { hasDuplicateCandidateSelection } from "../_shared/ballotSelection.js";
import { hasCurrentTermEnrollment } from "../_shared/currentTermEnrollment.js";
import { isWithinGeofence, parseCoordinates } from "../_shared/geofence.js";


function jsonResponse(body: Record<string, unknown>, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json",
    },
  });
}

function cleanText(value: unknown, maxLength = 255) {
  return String(value || "").trim().slice(0, maxLength);
}

function parsePositiveInteger(value: unknown, label: string) {
  const number = Number(value);
  if (!Number.isInteger(number) || number <= 0) {
    throw new Error(`${label} is required.`);
  }
  return number;
}

function parseScheduleWallClock(value: unknown) {
  if (!value) return null;
  const match = String(value).trim().match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?)?/,
  );

  if (!match) {
    const fallback = new Date(String(value));
    return Number.isNaN(fallback.getTime()) ? null : fallback;
  }

  const [, year, month, day, hour = "00", minute = "00", second = "00"] = match;
  return new Date(Date.UTC(
    Number(year),
    Number(month) - 1,
    Number(day),
    Number(hour) - 8,
    Number(minute),
    Number(second),
  ));
}

function getElectionPhase(election: Record<string, unknown>, now = new Date()) {
  const campaignStart = election?.campaign_start ? parseScheduleWallClock(election.campaign_start) : null;
  const campaignEnd = election?.campaign_end ? parseScheduleWallClock(election.campaign_end) : null;
  const votingStart = election?.start_date ? parseScheduleWallClock(election.start_date) : null;
  const votingEnd = election?.end_date ? parseScheduleWallClock(election.end_date) : null;
  const status = cleanText(election?.status, 40) || "draft";

  if (status === "draft") return "draft";
  if (status === "archived") return "archived";
  if (status === "closed") return "closed";
  // Dates never reopen a completed or otherwise nonactive election.
  if (status !== "active") return "closed";
  if (campaignStart && campaignEnd && now < campaignStart) return "campaign_upcoming";
  if (campaignStart && campaignEnd && now >= campaignStart && now < campaignEnd) return "campaign";
  if (campaignEnd && votingStart && now >= campaignEnd && now < votingStart) return "waiting";
  if (votingStart && votingEnd && now >= votingStart && now < votingEnd) return "voting";
  if (votingEnd && now >= votingEnd) return "closed";
  if (status === "active" && votingStart && now < votingStart) return "scheduled";
  return status;
}

type NormalizedVote = { position_id: number; candidate_id: number | null; is_abstain: boolean };

function normalizeSelectedVotes(selectedVotes: unknown): NormalizedVote[] {
  if (!selectedVotes || typeof selectedVotes !== "object") {
    throw new Error("Ballot selections are required.");
  }

  return Object.values(selectedVotes as Record<string, Record<string, unknown>>).flatMap<NormalizedVote>((vote) => {
    const positionId = parsePositiveInteger(vote.position_id, "Position");
    if (vote.is_abstain) {
      return [{
        position_id: positionId,
        candidate_id: null,
        is_abstain: true,
      }];
    }

    const candidateIds = Array.isArray(vote.candidate_ids)
      ? vote.candidate_ids
      : vote.candidate_id
        ? [vote.candidate_id]
        : [];

    return candidateIds.map((candidateId) => ({
      position_id: positionId,
      candidate_id: parsePositiveInteger(candidateId, "Candidate"),
      is_abstain: false,
    }));
  });
}

function safelyLogBackgroundNudgeFailure(
  error: unknown,
  context: Record<string, unknown>,
) {
  console.error("Ballot anchor background nudge failed:", {
    ...context,
    error: error instanceof Error ? error.message : String(error || "Unknown error."),
  });
}

async function nudgeBallotAnchorWorker(
  supabaseUrl: string,
  anonKey: string,
  workerToken: string,
  context: Record<string, unknown>,
) {
  try {
    const response = await fetch(`${supabaseUrl}/functions/v1/anchor-ballot-hashes`, {
      method: "POST",
      headers: {
        apikey: anonKey,
        Authorization: `Bearer ${anonKey}`,
        "Content-Type": "application/json",
        "x-anchor-worker-token": workerToken,
      },
      body: JSON.stringify({
        source: "submit-vote",
      }),
    });

    if (!response.ok) {
      console.error("Ballot anchor background nudge returned non-success status:", {
        ...context,
        status: response.status,
      });
      return;
    }

    console.log("Ballot anchor background nudge accepted:", {
      ...context,
      status: response.status,
    });
  } catch (error) {
    safelyLogBackgroundNudgeFailure(error, context);
  }
}

function scheduleBallotAnchorNudge(
  supabaseUrl: string,
  context: Record<string, unknown>,
) {
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const workerToken = Deno.env.get("ANCHOR_WORKER_TOKEN");

  if (!anonKey || !workerToken) {
    console.warn("Ballot anchor background nudge skipped: worker configuration is incomplete.", context);
    return;
  }

  const task = nudgeBallotAnchorWorker(supabaseUrl, anonKey, workerToken, context);
  const edgeRuntime = (
    globalThis as typeof globalThis & {
      EdgeRuntime?: { waitUntil?: (promise: Promise<unknown>) => void };
    }
  ).EdgeRuntime;

  if (typeof edgeRuntime?.waitUntil === "function") {
    edgeRuntime.waitUntil(task);
    return;
  }

  task.catch((error) => safelyLogBackgroundNudgeFailure(error, context));
  console.warn("Ballot anchor background nudge scheduled without EdgeRuntime.waitUntil support.", context);
}

serveWithKandidCors(async (request: Request) => {
  const preflightResponse = handleCorsPreflight(request);
  if (preflightResponse) return preflightResponse;

  const originRejection = rejectDisallowedOrigin(request);
  if (originRejection) return originRejection;

  if (request.method !== "POST") {
    return jsonResponse({ error: "Method not allowed." }, 405);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!supabaseUrl || !anonKey || !serviceRoleKey) {
    return jsonResponse({ error: "Server configuration is incomplete." }, 500);
  }

  const authorization = request.headers.get("Authorization");
  if (!authorization) {
    return jsonResponse({ error: "Your session has expired. Please sign in again." }, 401);
  }

  const authClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
    auth: { persistSession: false },
  });

  const {
    data: { user: authUser },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !authUser?.id) {
    return jsonResponse({ error: "Your session has expired. Please sign in again." }, 401);
  }

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ error: "Invalid JSON body." }, 400);
  }

  let electionId: number;
  let normalizedVotes: Array<{ position_id: number; candidate_id: number | null; is_abstain: boolean }>;

  try {
    electionId = parsePositiveInteger(body.election_id, "Election");
    normalizedVotes = normalizeSelectedVotes(body.selected_votes);
  } catch (error) {
    return jsonResponse({ error: error instanceof Error ? error.message : "Invalid ballot." }, 400);
  }

  if (normalizedVotes.length === 0) {
    return jsonResponse({ error: "Ballot selections are required." }, 400);
  }

  if (hasDuplicateCandidateSelection(normalizedVotes)) {
    return jsonResponse({ error: "A candidate can only be selected once for a position." }, 400);
  }

  const adminClient = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });

  const { data: student, error: studentError } = await adminClient
    .from("students")
    .select("id, auth_user_id, student_number, first_name, last_name, status, precinct_code, batch_code")
    .eq("auth_user_id", authUser.id)
    .maybeSingle();

  if (studentError || !student) {
    return jsonResponse({ error: "Your student account is not allowed to submit this ballot." }, 403);
  }

  if (student.auth_user_id !== authUser.id || student.status !== "active") {
    return jsonResponse({ error: "Your student account is not allowed to submit this ballot." }, 403);
  }

  const { data: election, error: electionError } = await adminClient
    .from("elections")
    .select("id, organization_id, academic_term_id, electorate_policy_version, electorate_frozen_at, status, campaign_start, campaign_end, start_date, end_date, voting_access_mode, geo_lat, geo_lng, geo_radius_meters")
    .eq("id", electionId)
    .single();

  if (electionError || !election?.organization_id) {
    console.error("ELECTION_VERIFY_FAILED", {
      electionId,
      election,
      error: electionError
        ? {
          message: electionError.message,
          code: electionError.code,
          details: electionError.details,
          hint: electionError.hint,
        }
        : null,
    });

    return jsonResponse({ error: "Election could not be verified." }, 404);
  }

  if (getElectionPhase(election, new Date()) !== "voting") {
    return jsonResponse({ error: "Voting is not open for this election right now." }, 409);
  }

  const votingAccessMode = cleanText(election.voting_access_mode, 40) || "anywhere";
  if (votingAccessMode === "location_range") {
    const coordinates = parseCoordinates(body.location);
    if (!coordinates || !isWithinGeofence(
      coordinates, election.geo_lat, election.geo_lng, election.geo_radius_meters,
    )) {
      return jsonResponse({ error: "Voting access could not be verified for this location." }, 403);
    }
  } else if (["onsite_qr", "precinct_qr", "batch_qr"].includes(votingAccessMode)) {
    const token = cleanText(body.access_code, 64).toUpperCase();
    if (!token) return jsonResponse({ error: "A valid voting access code is required." }, 403);
    const { data: accessToken, error: tokenError } = await adminClient.from("election_access_tokens")
      .select("is_active, scope_type, scope_value, expires_at")
      .eq("election_id", electionId).eq("token", token).maybeSingle();
    if (tokenError) return jsonResponse({ error: "Voting access could not be verified." }, 503);
    if (!accessToken?.is_active || (accessToken.expires_at && new Date(accessToken.expires_at).getTime() < Date.now())) {
      return jsonResponse({ error: "A valid voting access code is required." }, 403);
    }
    const normalizeScope = (value: unknown) => String(value || "").trim().toUpperCase();
    const scopeAllowed = accessToken.scope_type === "general"
      || (accessToken.scope_type === "precinct" && normalizeScope(accessToken.scope_value) !== ""
        && normalizeScope(accessToken.scope_value) === normalizeScope(student.precinct_code))
      || (accessToken.scope_type === "batch" && normalizeScope(accessToken.scope_value) !== ""
        && normalizeScope(accessToken.scope_value) === normalizeScope(student.batch_code));
    if (!scopeAllowed) return jsonResponse({ error: "A valid voting access code is required." }, 403);
  } else if (votingAccessMode !== "anywhere") {
    return jsonResponse({ error: "Voting access could not be verified." }, 409);
  }

  if (Number(election.electorate_policy_version) === 1) {
    if (!election.electorate_frozen_at || !election.academic_term_id) {
      return jsonResponse({
        error: "Voting is unavailable because this election's electorate has not been locked.",
        electorate_unlocked: true,
      }, 409);
    }

    const { data: activeTerms, error: activeTermError } = await adminClient
      .from("academic_terms")
      .select("id")
      .eq("status", "active")
      .limit(2);

    if (activeTermError) {
      console.error("Current academic term could not be verified:", activeTermError.message);
      return jsonResponse({ error: "Current enrollment could not be verified." }, 503);
    }

    if (activeTerms?.length !== 1 || Number(activeTerms[0]?.id) !== Number(election.academic_term_id)) {
      return jsonResponse({ error: "This student is not enrolled for the current academic term." }, 403);
    }

    const activeTermId = Number(activeTerms[0].id);
    const { data: enrollmentRows, error: enrollmentError } = await adminClient
      .from("student_term_enrollments")
      .select("student_id, academic_term_id, enrollment_status")
      .eq("student_id", Number(student.id))
      .eq("academic_term_id", activeTermId)
      .eq("enrollment_status", "enrolled")
      .limit(1);

    if (enrollmentError) {
      console.error("Current Student enrollment could not be verified:", enrollmentError.message);
      return jsonResponse({ error: "Current enrollment could not be verified." }, 503);
    }

    if (!hasCurrentTermEnrollment({
      studentId: Number(student.id),
      activeTermId,
      electionTermId: Number(election.academic_term_id),
      enrollmentRows,
    })) {
      return jsonResponse({ error: "This student is not enrolled for the current academic term." }, 403);
    }

    // A frozen electorate is an admission snapshot, but current-term
    // organization participation can be revoked after a program change.
    // Require both the frozen roster and the live term-scoped membership.
    const { data: participationRows, error: participationError } = await adminClient.rpc(
      "resolve_student_organization_participation",
      {
        target_student_id: Number(student.id),
        target_organization_id: Number(election.organization_id),
        target_academic_term_id: activeTermId,
      },
    );
    const participation = Array.isArray(participationRows)
      ? participationRows[0]
      : participationRows;
    if (participationError || participation?.allowed !== true) {
      return jsonResponse({ error: "This student is not eligible for this election." }, 403);
    }

    const { data: isElectorateMember, error: electorateError } = await adminClient.rpc(
      "kandid_is_locked_electorate_member",
      {
        p_election_id: electionId,
        p_student_id: Number(student.id),
      },
    );

    if (electorateError) {
      console.error("Locked electorate membership could not be verified:", electorateError.message);
      return jsonResponse({ error: "This student is not eligible for this election." }, 403);
    }
    if (isElectorateMember !== true) {
      return jsonResponse({ error: "This student is not eligible for this election." }, 403);
    }
  } else if (Number(election.electorate_policy_version) === 0) {
    // Explicit legacy compatibility only. New frozen-policy elections never
    // fall back to this live resolver after the lock boundary.
    const { data: activeTerm, error: termError } = await adminClient
      .from("academic_terms")
      .select("id")
      .eq("status", "active")
      .order("created_at", { ascending: false })
      .order("id", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (termError || !activeTerm?.id) {
      return jsonResponse({ error: "Active academic term could not be verified." }, 409);
    }

    const { data: participationRows, error: participationError } = await adminClient.rpc(
      "resolve_student_organization_participation",
      {
        target_student_id: Number(student.id),
        target_organization_id: Number(election.organization_id),
        target_academic_term_id: Number(activeTerm.id),
      },
    );

    const participation = Array.isArray(participationRows)
      ? participationRows[0]
      : participationRows;

    if (participationError || participation?.allowed !== true) {
      return jsonResponse({ error: "This student is not eligible for this election." }, 403);
    }
  } else {
    console.error("Election electorate policy is missing or unsupported.", { electionId });
    return jsonResponse({ error: "Election eligibility could not be verified." }, 409);
  }

  const { data: positions, error: positionError } = await adminClient
    .from("positions")
    .select("id, max_votes")
    .eq("election_id", electionId)
    .eq("status", "active");

  if (positionError) {
    return jsonResponse({ error: "Unable to verify ballot positions." }, 500);
  }

  const positionById = new Map((positions || []).map((position) => [Number(position.id), position]));
  if (positionById.size === 0) {
    return jsonResponse({ error: "No ballot positions found for this election." }, 400);
  }

  const votesByPosition = new Map<number, Array<{ position_id: number; candidate_id: number | null; is_abstain: boolean }>>();
  normalizedVotes.forEach((vote) => {
    const current = votesByPosition.get(vote.position_id) || [];
    current.push(vote);
    votesByPosition.set(vote.position_id, current);
  });

  if (votesByPosition.size !== positionById.size) {
    return jsonResponse({ error: "Please select a vote or abstain for every position." }, 400);
  }

  for (const [positionId, votes] of votesByPosition.entries()) {
    const position = positionById.get(positionId);
    if (!position) {
      return jsonResponse({ error: "Ballot includes a position that does not belong to this election." }, 400);
    }

    const abstainCount = votes.filter((vote) => vote.is_abstain).length;
    const candidateVotes = votes.filter((vote) => !vote.is_abstain);
    const maxVotes = Math.max(Number(position.max_votes || 1), 1);

    if (abstainCount > 0 && votes.length > 1) {
      return jsonResponse({ error: "Abstain cannot be combined with candidate selections." }, 400);
    }

    if (abstainCount === 0 && candidateVotes.length === 0) {
      return jsonResponse({ error: "Please select a candidate or abstain for every position." }, 400);
    }

    if (candidateVotes.length > maxVotes) {
      return jsonResponse({ error: "A position has more selected candidates than allowed." }, 400);
    }
  }

  const candidateIds = normalizedVotes
    .map((vote) => vote.candidate_id)
    .filter((candidateId): candidateId is number => Number.isInteger(candidateId));

  if (candidateIds.length > 0) {
    const { data: candidates, error: candidateError } = await adminClient
      .from("candidates")
      .select("id, position_id")
      .in("id", candidateIds);

    if (candidateError) {
      return jsonResponse({ error: "Unable to verify ballot candidates." }, 500);
    }

    const candidateById = new Map((candidates || []).map((candidate) => [Number(candidate.id), candidate]));
    for (const vote of normalizedVotes) {
      if (vote.candidate_id == null) continue;
      const candidate = candidateById.get(Number(vote.candidate_id));
      if (!candidate || Number(candidate.position_id) !== Number(vote.position_id)) {
        return jsonResponse({ error: "Ballot includes a candidate that does not belong to the selected position." }, 400);
      }
    }
  }

  const { data: insertedVotes, error: insertError } = await adminClient.rpc(
    "insert_v2_vote_rows",
    {
      p_student_id: Number(student.id),
      p_election_id: electionId,
      p_votes: normalizedVotes,
    },
  );

  if (insertError) {
    const message = String(insertError.message || "");

    if (message.includes("This student has already voted in this election.")) {
      return jsonResponse(
        {
          error: "This student has already voted in this election.",
          already_voted: true,
        },
        409,
      );
    }

    console.error("V2 vote insertion failed:", insertError);
    return jsonResponse({ error: "Vote could not be recorded." }, 500);
  }

  const createdVotes = Array.isArray(insertedVotes) ? insertedVotes : [];

  if (createdVotes.length === 0) {
    console.error("V2 vote insertion returned no rows.");
    return jsonResponse({ error: "Vote could not be recorded." }, 500);
  }

  const submittedAt = String(
    createdVotes[0]?.canonical_vote_timestamp || "",
  );
  const ballotId = typeof createdVotes[0]?.ballot_id === "string"
    ? createdVotes[0].ballot_id
    : null;

  const responseBody = {
    data: {
      submitted_at: submittedAt,
      vote_count: createdVotes.length,
      ballot_id: ballotId,
    },
  };

  scheduleBallotAnchorNudge(supabaseUrl, {
    ballot_id: ballotId,
    election_id: electionId,
    vote_count: createdVotes.length,
  });

  return jsonResponse(responseBody);
});

export const KANDID_WEB_ORIGIN = "https://witkandid.vercel.app";
export const KANDID_WEB_ORIGINS = Object.freeze([
  KANDID_WEB_ORIGIN,
  "http://localhost:5173",
  "http://localhost:5174",
]);
export const ADMIN_INVITE_REDIRECT_URL = `${KANDID_WEB_ORIGIN}/admin-auth/setup`;

const BASE_CORS_HEADERS = Object.freeze({
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-retry-count",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Max-Age": "600",
  "Vary": "Origin",
});

export const corsHeaders = Object.freeze({
  ...BASE_CORS_HEADERS,
  "Access-Control-Allow-Origin": KANDID_WEB_ORIGIN,
});

export function corsHeadersForOrigin(origin) {
  if (!KANDID_WEB_ORIGINS.includes(origin)) return null;
  return {
    ...BASE_CORS_HEADERS,
    "Access-Control-Allow-Origin": origin,
  };
}

export function withKandidCors(request, response) {
  const origin = request.headers.get("origin");
  const allowedHeaders = corsHeadersForOrigin(origin);
  if (!allowedHeaders) return response;

  const headers = new Headers(response.headers);
  for (const [name, value] of Object.entries(allowedHeaders)) {
    if (name.toLowerCase() === "vary" && headers.has(name)) {
      const vary = new Set([
        ...headers.get(name).split(",").map((item) => item.trim()),
        ...value.split(",").map((item) => item.trim()),
      ].filter(Boolean));
      headers.set(name, [...vary].join(", "));
    } else {
      headers.set(name, value);
    }
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export function serveWithKandidCors(handler) {
  return Deno.serve(async (request) => {
    const response = await handler(request);
    return withKandidCors(request, response);
  });
}

const ALLOWED_PREFLIGHT_HEADERS = new Set([
  "authorization",
  "x-client-info",
  "apikey",
  "content-type",
  "x-retry-count",
]);
const PREFLIGHT_VARY = "Origin, Access-Control-Request-Method, Access-Control-Request-Headers";

function rejectedOriginResponse() {
  return new Response(JSON.stringify({ error: "Origin not allowed." }), {
    status: 403,
    headers: {
      "Content-Type": "application/json",
      "Vary": "Origin",
    },
  });
}

export function rejectDisallowedOrigin(request) {
  const origin = request.headers.get("origin");
  if (origin === null || KANDID_WEB_ORIGINS.includes(origin)) return null;
  return rejectedOriginResponse();
}

export function handleCorsPreflight(request) {
  if (request.method !== "OPTIONS") return null;

  const origin = request.headers.get("origin");
  if (origin === null) {
    const requestedMethod = request.headers.get("access-control-request-method")?.toUpperCase();
    if (requestedMethod && requestedMethod !== "POST") {
      return new Response(null, {
        status: 403,
        headers: { "Allow": "POST, OPTIONS" },
      });
    }
    return new Response(null, {
      status: 204,
      headers: { "Allow": "POST, OPTIONS" },
    });
  }

  const responseHeaders = corsHeadersForOrigin(origin);
  if (!responseHeaders) {
    return rejectedOriginResponse();
  }

  const requestedMethod = request.headers.get("access-control-request-method")?.toUpperCase();
  if (requestedMethod !== "POST") {
    return new Response(null, {
      status: 403,
        headers: { ...responseHeaders, "Vary": PREFLIGHT_VARY },
    });
  }

  const requestedHeaders = (request.headers.get("access-control-request-headers") || "")
    .split(",")
    .map((header) => header.trim().toLowerCase())
    .filter(Boolean);
  if (requestedHeaders.some((header) => !ALLOWED_PREFLIGHT_HEADERS.has(header))) {
    return new Response(null, {
      status: 403,
        headers: { ...responseHeaders, "Vary": PREFLIGHT_VARY },
    });
  }

  return new Response(null, {
    status: 204,
    headers: { ...responseHeaders, "Vary": PREFLIGHT_VARY },
  });
}

export function resolveAdminInviteRedirect(configuredValue) {
  const target = String(configuredValue || ADMIN_INVITE_REDIRECT_URL).trim();
  let url;
  try {
    url = new URL(target);
  } catch {
    throw new Error("Administrator invite redirect is invalid.");
  }

  if (
    url.protocol !== "https:" ||
    url.origin !== KANDID_WEB_ORIGIN ||
    url.pathname !== "/admin-auth/setup" ||
    url.search ||
    url.hash
  ) {
    throw new Error("Administrator invite redirect must use the official setup route.");
  }

  return url.toString();
}

export function hasDuplicateCandidateSelection(selections = []) {
  const seen = new Set();
  for (const selection of selections) {
    if (selection?.is_abstain || selection?.candidate_id == null) continue;
    const key = `${Number(selection.position_id)}:${Number(selection.candidate_id)}`;
    if (seen.has(key)) return true;
    seen.add(key);
  }
  return false;
}

function positiveInteger(value) {
  const number = Number(value);
  return Number.isSafeInteger(number) && number > 0 ? number : null;
}

export function hasCurrentTermEnrollment({
  studentId,
  activeTermId,
  electionTermId,
  enrollmentRows,
}) {
  const student = positiveInteger(studentId);
  const activeTerm = positiveInteger(activeTermId);
  const electionTerm = positiveInteger(electionTermId);

  if (!student || !activeTerm || !electionTerm || activeTerm !== electionTerm) {
    return false;
  }

  return (Array.isArray(enrollmentRows) ? enrollmentRows : []).some((row) =>
    positiveInteger(row?.student_id) === student &&
    positiveInteger(row?.academic_term_id) === activeTerm &&
    String(row?.enrollment_status || "").toLowerCase() === "enrolled"
  );
}

export function parseCoordinates(value) {
  if (!value || typeof value !== "object") return null;
  const point = value;
  if (typeof point.latitude !== "number" || typeof point.longitude !== "number") return null;
  if (!Number.isFinite(point.latitude) || !Number.isFinite(point.longitude)) return null;
  if (point.latitude < -90 || point.latitude > 90 || point.longitude < -180 || point.longitude > 180) return null;
  return { latitude: point.latitude, longitude: point.longitude };
}

export function isWithinGeofence(point, centerLatitude, centerLongitude, radiusMeters) {
  const latitude = Number(centerLatitude);
  const longitude = Number(centerLongitude);
  const radius = Number(radiusMeters);
  if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) return false;
  if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) return false;
  if (!Number.isFinite(radius) || radius <= 0) return false;
  const radians = (degrees) => degrees * Math.PI / 180;
  const dLat = radians(latitude - point.latitude);
  const dLng = radians(longitude - point.longitude);
  const a = Math.sin(dLat / 2) ** 2
    + Math.cos(radians(point.latitude)) * Math.cos(radians(latitude)) * Math.sin(dLng / 2) ** 2;
  const distance = 2 * 6371000 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return distance <= radius;
}
